  public void initCommandProducer() {
    registry.addCommandProducer(
        "metamodel-repository-proxy",
        org.tura.platform.repository.cpa.operation.CpaCommandProducer.class);
    spaRegistry
        .getRegistry("metamodel-repository-proxy")
        .addInstantiator(new CPARepositoryInstantiator(registry, spaRegistry));
    spaRegistry
        .getRegistry("metamodel-repository-proxy")
        .addExternalCommand(
            org.tura.platform.repository.cpa.operation.CpaStorageControlOperation.class);
  }

  public void initRules() {
    registry.addRule(
        org.tura.platform.repository.core.navigation.NavigationRuleTypes
            .AddObject_ValidateIsObjectContainment.name(),
        org.tura.platform.repository.core.navigation.AddObjectsDefaultRule.class);
    registry.addRule(
        org.tura.platform.repository.core.navigation.NavigationRuleTypes
            .AddObject_ValidateIsObjectContainment.name(),
        org.tura.platform.repository.cpa.navigation.AddObjectsRule.class);
  }
